typedef float rational_t;

class vector3d
{
public:
  typedef rational_t T;
  T x,y,z;
  inline vector3d() {}
  inline vector3d(const vector3d& v) { x = v.x; y = v.y; z = v.z; }
  inline vector3d(T _x, T _y, T _z) { x = _x; y = _y; z = _z; }
};

inline vector3d operator + (const vector3d& a, const vector3d& b)
{ return vector3d(a.x + b.x, a.y + b.y, a.z + b.z); }

class vm_stack
{
public:
  int salloc;
  char* buffer;
  char* SP;
  void pop(int n) { SP -= n; }
  char* get_SP() const { return SP; }
  bool push(const char* src, int n);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t { FIRST_ENTRY, RECALL_ENTRY };
    virtual bool operator()(vm_stack& stack,entry_t entry) { return true; }
  };
};

class slf_vector3d_add_t : public script_library_class::function
{
public:
  struct parms_t
  {
    vector3d me;
    vector3d b;
  };
  virtual bool operator()(vm_stack& stack,entry_t entry)
  {
    stack.pop(sizeof(parms_t));
    parms_t* parms = (parms_t*)stack.get_SP();
    vector3d result = parms->me + parms->b;
    if (!stack.push((char*)&result,sizeof(result)) )
      ;
    return true;
  }
};
